{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Rosaramicin, a macrocyclic lactone antibiotic, had an absolute oral bioavailability of 39 ± 8% in normal volunteers, showing that lactone-rich natural products can exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Retrorsine, a polycyclic natural-product lactone, was predicted to have 44% oral bioavailability, supporting high F for complex lactone-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "9-Aminocamptothecin, a lipophilic camptothecin lactone, showed 49 ± 18% absolute oral bioavailability in patients, supporting F > 20% for lactone-containing molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Topotecan, a camptothecin lactone, had 42 ± 13% absolute oral bioavailability in patients, supporting F > 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "9-Nitrocamptothecin, a highly lipophilic lactone, had very low absolute oral bioavailability, providing a contradictory example for lipophilic lactones.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polycyclic diterpenoid lactone with multiple polar groups and a tert-butyl substituent. Most transferable experimental F values for complex lactone natural products (rosaramicin 39%, retrorsine 44%, 9-aminocamptothecin ~49%, topotecan 42%) are above the 20% threshold. The low-F examples are either qualitative (artemisinin reports) or structurally less transferable (9-nitrocamptothecin, amphotericin B). On balance, high oral bioavailability at the F ≥ 20% threshold is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the query molecule.",
    "All retrieved analogues have low Morgan similarity (<0.2), limiting structural transferability.",
    "Several artemisinin low-bioavailability reports are qualitative and do not clearly establish F < 20%.",
    "Potential species differences in oral absorption and first-pass metabolism are not fully resolved."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

